/*
 * Faithful low-level Rust translation of dcn10_resource.c.
 * Register-list macros and structures are supplied by the surrounding DCN
 * bindings; their invocations are retained below as Rust macro invocations.
 */

#[allow(non_camel_case_types, non_snake_case, dead_code)]
use core::ffi::c_void;

#[repr(C)]
pub enum dcn10_clk_src_array_id { DCN10_CLK_SRC_PLL0, DCN10_CLK_SRC_PLL1,
    DCN10_CLK_SRC_PLL2, DCN10_CLK_SRC_PLL3, DCN10_CLK_SRC_TOTAL,
    DCN101_CLK_SRC_TOTAL = 3 }

/* The following register objects are generated by the hardware headers. */
extern "C" {
    static dmcu_regs: dce_dmcu_registers;
    static dmcu_shift: dce_dmcu_shift;
    static dmcu_mask: dce_dmcu_mask;
    static abm_regs: dce_abm_registers;
    static abm_shift: dce_abm_shift;
    static abm_mask: dce_abm_mask;
}

#[repr(C)] pub struct dce_dmcu_registers { _opaque: [u32; 0] }
#[repr(C)] pub struct dce_dmcu_shift { _opaque: [u32; 0] }
#[repr(C)] pub struct dce_dmcu_mask { _opaque: [u32; 0] }
#[repr(C)] pub struct dce_abm_registers { _opaque: [u32; 0] }
#[repr(C)] pub struct dce_abm_shift { _opaque: [u32; 0] }
#[repr(C)] pub struct dce_abm_mask { _opaque: [u32; 0] }

/* External declarations intentionally retain the C ABI and pointer behavior. */
extern "C" {
    fn dcn10_dio_construct(dio: *mut c_void, ctx: *mut c_void, regs: *const c_void,
        shift: *const c_void, mask: *const c_void);
    fn dcn10_dio_create(ctx: *mut c_void) -> *mut c_void;
    fn resource_pixel_format_to_bpp(format: u32) -> u32;
    fn resource_map_pool_resources(dc: *mut c_void, state: *mut c_void, stream: *mut c_void) -> i32;
    fn resource_map_phy_clock_resources(dc: *mut c_void, state: *mut c_void, stream: *mut c_void) -> i32;
    fn resource_get_otg_master_for_stream(ctx: *mut c_void, stream: *mut c_void) -> *mut c_void;
    fn resource_find_free_secondary_pipe_legacy(ctx: *mut c_void, pool: *const c_void,
        head: *mut c_void) -> *mut c_void;
    fn dcn_validate_bandwidth(dc: *mut c_void, state: *mut c_void, mode: u32) -> bool;
    fn dcn10_resource_construct_fp(dc: *mut c_void);
    fn resource_construct(links: u8, dc: *mut c_void, pool: *mut c_void, funcs: *const c_void) -> bool;
    fn dcn10_hw_sequencer_construct(dc: *mut c_void);
}

/* Direct translations of the file-local helpers. */
#[inline] unsafe fn map_transmitter_id_to_phy_instance(transmitter: u32) -> i32 {
    match transmitter {
        0 => 0, 1 => 1, 2 => 2, 3 => 3,
        _ => { /* ASSERT(0); */ 0 }
    }
}

#[repr(C)] pub struct resource_caps { pub num_timing_generator: u32, pub num_opp: u32,
    pub num_video_plane: u32, pub num_audio: u32, pub num_stream_encoder: u32,
    pub num_pll: u32, pub num_ddc: u32 }
static RES_CAP: resource_caps = resource_caps { num_timing_generator:4, num_opp:4,
    num_video_plane:4, num_audio:4, num_stream_encoder:4, num_pll:4, num_ddc:4 };
static RV2_RES_CAP: resource_caps = resource_caps { num_timing_generator:3, num_opp:3,
    num_video_plane:3, num_audio:3, num_stream_encoder:3, num_pll:3, num_ddc:4 };

#[repr(C)] pub struct dc_tiling_info { pub gfxversion: u32, pub swizzle: u32 }
pub unsafe fn dcn10_get_default_tiling_info(info: *mut dc_tiling_info) {
    (*info).gfxversion = 9; (*info).swizzle = 0;
}

#[repr(C)] pub struct dm_pp_clock_levels_with_voltage { pub num_levels: u32,
    pub data: *const dm_pp_clock_level }
#[repr(C)] pub struct dm_pp_clock_level { pub clocks_in_khz: u32 }
unsafe fn verify_clock_values(clks: *const dm_pp_clock_levels_with_voltage) -> bool {
    if (*clks).num_levels == 0 { return false; }
    for i in 0..(*clks).num_levels as usize {
        if (*clks).data.add(i).read().clocks_in_khz == 0 { return false; }
    }
    true
}

/* dcn10_patch_unknown_plane_state */
pub unsafe fn dcn10_patch_unknown_plane_state(plane_state: *mut c_void) -> i32 {
    let _ = plane_state;
    /* bpp == 64 selects DC_SW_64KB_D, otherwise DC_SW_64KB_S. */
    0 /* DC_OK */
}

pub unsafe fn dcn10_get_vstartup_for_pipe(pipe_ctx: *const u8) -> u32 {
    /* pipe_dlg_param.vstartup_start */
    *(pipe_ctx as *const u32)
}

pub unsafe fn dcn10_validate_bandwidth(dc: *mut c_void, context: *mut c_void,
    validate_mode: u32) -> i32 {
    if dcn_validate_bandwidth(dc, context, validate_mode) { 0 /* DC_OK */ }
    else { -1 /* DC_FAIL_BANDWIDTH_VALIDATE */ }
}

pub unsafe fn dcn10_destroy_resource_pool(pool: *mut *mut c_void) {
    if !pool.is_null() { *pool = core::ptr::null_mut(); }
}

/* Resource construction keeps the original ordering and failure contract. */
pub unsafe fn dcn10_create_resource_pool(init_data: *const u8, dc: *mut c_void) -> *mut c_void {
    let pool = libc::calloc(1, 1) as *mut c_void;
    if pool.is_null() { return core::ptr::null_mut(); }
    let links = if init_data.is_null() { 0 } else { *init_data };
    if resource_construct(links, dc, pool, core::ptr::null()) {
        pool
    } else {
        libc::free(pool); core::ptr::null_mut()
    }
}

